using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Npgsql;
using PGMS.Desktop;
using PGMS.PostgreSql;

internal static class IdentityColumnDialogChecks
{
    private static T Find<T>(Window window,string name)where T:FrameworkElement=>(T)window.FindName(name);
    private static void Select(Window window,ColumnIdentity mode)=>Find<ComboBox>(window,"IdentitySelector").SelectedItem=Find<ComboBox>(window,"IdentitySelector").Items.Cast<ColumnIdentityChoice>().Single(c=>c.Value==mode);
    private static async Task Modal(Window window,Func<Task> body)
    {
        var done=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        window.Loaded+=async(_,_)=>{try{await body();done.TrySetResult();}catch(Exception ex){done.TrySetException(ex);}finally{if(window.IsVisible)window.Close();}};
        window.ShowDialog();await done.Task;
    }
    private static async Task Capture(Window dialog,string name,double width,double height,Action<bool,string> check)
    {
        dialog.Width=width;dialog.Height=height;
        await dialog.Dispatcher.InvokeAsync(()=>{},System.Windows.Threading.DispatcherPriority.ApplicationIdle);
        dialog.UpdateLayout();var root=(FrameworkElement)dialog.Content;
        foreach(string action in new[]{"ScriptButton","ApplyButton","CloseButton"})
        {var button=Find<Button>(dialog,action);var p=button.TranslatePoint(new Point(),root);check(p.Y>=-0.1 && p.Y+button.ActualHeight<=root.ActualHeight+0.1,"Identity action fits viewport: "+name+"/"+action+" (top="+p.Y.ToString("R")+",height="+button.ActualHeight.ToString("R")+",viewport="+root.ActualHeight.ToString("R")+")");}
        check(Find<TextBox>(dialog,"Preview").ActualHeight>=28,"Identity SQL retains a readable viewport: "+name);
        var bitmap=new RenderTargetBitmap((int)Math.Ceiling(root.ActualWidth),(int)Math.Ceiling(root.ActualHeight),96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen()){var rect=new Rect(0,0,root.ActualWidth,root.ActualHeight);dc.DrawRectangle(dialog.Background,null,rect);dc.DrawRectangle(new VisualBrush(root),null,rect);}bitmap.Render(drawing);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));Directory.CreateDirectory("artifacts/review");using var file=File.Create("artifacts/review/m744-"+name+".png");encoder.Save(file);
    }
    internal static async Task RunAsync(string connection,Action<bool,string> check)
    {
        string suffix=Guid.NewGuid().ToString("N"),schema="identity_ui_"+suffix,owner="identity_ui_owner_"+suffix;
        string qs=SqlIdentifier.Quote(schema),qo=SqlIdentifier.Quote(owner),table=ObjectSql.Relation(schema,"created");
        await using var admin=new NpgsqlConnection(connection);await admin.OpenAsync();
        async Task Sql(string sql){await using var cmd=new NpgsqlCommand(sql,admin);await cmd.ExecuteNonQueryAsync();}
        string limited=new NpgsqlConnectionStringBuilder(connection){Username=owner,Pooling=false}.ConnectionString;
        var layouts=new List<(bool Valid,string Message)>();
        void Layout(bool valid,string message)=>layouts.Add((valid,message));
        try
        {
            await Sql($"CREATE ROLE {qo} LOGIN;CREATE SCHEMA {qs} AUTHORIZATION {qo}");
            var create=new CreateTableDialog(limited,schema){ShowInTaskbar=false};
            await Modal(create,async()=>
            {
                Find<TextBox>(create,"TableName").Text="created";Find<TextBox>(create,"ColumnName").Text="id";
                check(Find<ComboBox>(create,"IdentitySelector").SelectedItem is ColumnIdentityChoice{Value:ColumnIdentity.None},"New Table identity defaults to None");
                Select(create,ColumnIdentity.ByDefault);
                check(Find<CheckBox>(create,"Nullable").IsChecked==false && !Find<CheckBox>(create,"Nullable").IsEnabled,"Selecting identity makes NOT NULL explicit and prevents nullable conflict");
                Find<Button>(create,"AddButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                check(Find<TextBox>(create,"Preview").Text.Contains("GENERATED BY DEFAULT AS IDENTITY NOT NULL",StringComparison.Ordinal),"New Table previews the selected identity clause");
                Find<ComboBox>(create,"DataType").SelectedItem=ColumnType.Text;
                check(!Find<Button>(create,"AddButton").IsEnabled && Find<TextBlock>(create,"IdentityHelp").Text.Contains("smallint",StringComparison.Ordinal),"Unsupported identity type disables Add with an actionable correction");
                Select(create,ColumnIdentity.None);
                check(Find<CheckBox>(create,"Nullable").IsChecked==true && Find<CheckBox>(create,"Nullable").IsEnabled,"Leaving identity restores the user's prior nullable choice");
                Find<TextBox>(create,"ColumnName").Text="note";Find<Button>(create,"AddButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                check(Find<DataGrid>(create,"ColumnGrid").Items.Cast<TableColumn>().First().Identity==ColumnIdentity.ByDefault,"Added column retains identity independently of the next proposal");
                await Capture(create,"new-table-normal",800,710,Layout);await Capture(create,"new-table-small",710,660,Layout);
                await create.ApplyAsync();check(create.WasApplied,"New Table identity executes as an ordinary schema owner");
            });
            await using var client=new NpgsqlConnection(limited);await client.OpenAsync();
            async Task<object?> Scalar(string sql){await using var cmd=new NpgsqlCommand(sql,client);return await cmd.ExecuteScalarAsync();}
            check(Convert.ToInt64(await Scalar($"INSERT INTO {table}(note) VALUES('first') RETURNING id"))==1,"WPF-created identity generates real first value");
            await Scalar($"INSERT INTO {table}(note) VALUES('second')");
            var inspected=await new TablePropertiesService(limited).InspectAsync(schema,"created");
            var add=new TableEditDialog(limited,inspectedTable:inspected){ShowInTaskbar=false};
            await Modal(add,async()=>
            {
                Find<ComboBox>(add,"Operation").SelectedItem=TableOperation.AddColumn;Find<TextBox>(add,"ColumnName").Text="secondary";Find<ComboBox>(add,"ColumnTypeSelector").SelectedItem=ColumnType.Smallint;Select(add,ColumnIdentity.Always);
                check(Find<TextBox>(add,"Preview").Text.Contains("smallint GENERATED ALWAYS AS IDENTITY NOT NULL",StringComparison.Ordinal) && !Find<CheckBox>(add,"AllowNull").IsEnabled,"Add Column previews ALWAYS identity with explicit NOT NULL");
                Find<ComboBox>(add,"ColumnTypeSelector").SelectedItem=ColumnType.Text;
                check(!Find<Button>(add,"ApplyButton").IsEnabled && Find<TextBox>(add,"Preview").Text.Length==0,"Add Column refuses an incompatible identity type before SQL");
                Find<ComboBox>(add,"ColumnTypeSelector").SelectedItem=ColumnType.Smallint;
                foreach(string control in new[]{"IdentitySelector","IdentityHelp"})check(!string.IsNullOrWhiteSpace(System.Windows.Automation.AutomationProperties.GetName(Find<FrameworkElement>(add,control))),"Added identity control is named for automation: "+control);
                await Capture(add,"add-identity-normal",760,820,Layout);await Capture(add,"add-identity-small",680,760,Layout);
                await add.ApplyAsync();check(add.WasApplied,"WPF adds identity under the inspected table identity guard");
            });
            check(Convert.ToInt64(await Scalar($"SELECT count(DISTINCT secondary) FROM {table}"))==2,"WPF-added identity fills existing rows");
            check(Convert.ToInt64(await Scalar($"INSERT INTO {table}(note) VALUES('third') RETURNING secondary"))==3,"WPF-added identity continues its independent sequence");
            bool explicitRefused=false;try{await Scalar($"INSERT INTO {table}(secondary,note) VALUES(88,'explicit')");}catch(PostgresException ex)when(ex.SqlState=="428C9"){explicitRefused=true;}
            check(explicitRefused,"WPF-selected ALWAYS mode refuses an explicit identity value");
            var script=new CreateTableDialog(limited,schema){ShowInTaskbar=false};
            await Modal(script,()=>
            {
                Find<TextBox>(script,"TableName").Text="script_only";Find<TextBox>(script,"ColumnName").Text="id";Find<ComboBox>(script,"DataType").SelectedItem=ColumnType.Bigint;Select(script,ColumnIdentity.Always);Find<Button>(script,"AddButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Find<Button>(script,"ScriptButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));return Task.CompletedTask;
            });
            check(script.ScriptSql!.Contains("bigint GENERATED ALWAYS AS IDENTITY NOT NULL",StringComparison.Ordinal) && !script.WasApplied,"Identity Script returns exact generation SQL without applying");
            await using var missing=new NpgsqlCommand("SELECT to_regclass(@table) IS NULL",client);missing.Parameters.AddWithValue("table",ObjectSql.Relation(schema,"script_only"));check((bool)(await missing.ExecuteScalarAsync())!,"Identity Script creates no table or implicit sequence");
            foreach(var result in layouts)check(result.Valid,result.Message);
        }
        finally{await Sql($"DROP SCHEMA IF EXISTS {qs} CASCADE;DROP ROLE IF EXISTS {qo}");}
    }
}
